export interface LiveTranscriptTurn {
	user: string;
	assistant: string;
}

export interface LiveTranscriptState {
	turns: LiveTranscriptTurn[];
	draft: LiveTranscriptTurn;
}

export type LiveTranscriptRole = keyof LiveTranscriptTurn;

export function emptyLiveTranscript(): LiveTranscriptState {
	return {
		turns: [],
		draft: { user: "", assistant: "" },
	};
}

function mergeTranscript(current: string, text: string, final: boolean): string {
	if (final) return text || current;
	return current + text;
}

function completedDraft(state: LiveTranscriptState): LiveTranscriptState {
	const user = state.draft.user.trim();
	const assistant = state.draft.assistant.trim();
	if (!user && !assistant) return state;
	return {
		turns: [...state.turns, { user, assistant }],
		draft: { user: "", assistant: "" },
	};
}

/**
 * Fold provider transcript callbacks into conversational turns.
 *
 * OpenAI completes a turn with the full assistant transcript while Gemini
 * completes it with an empty final marker. In both cases, an assistant final
 * closes the user/assistant pair. User finals only settle their side of the
 * draft because the answer is still on its way.
 */
export function appendLiveTranscript(
	state: LiveTranscriptState,
	role: LiveTranscriptRole,
	text: string,
	final: boolean,
): LiveTranscriptState {
	const next = {
		...state,
		draft: {
			...state.draft,
			[role]: mergeTranscript(state.draft[role], text, final),
		},
	};
	return role === "assistant" && final ? completedDraft(next) : next;
}

/** Preserve a partially transcribed turn when the learner ends the session. */
export function flushLiveTranscript(state: LiveTranscriptState): LiveTranscriptState {
	return completedDraft(state);
}
import { describe, expect, it } from "bun:test";

import {
	appendLiveTranscript,
	emptyLiveTranscript,
	flushLiveTranscript,
} from "../keating/live-transcript";

describe("live transcript turn accumulation", () => {
	it("groups streaming user and assistant deltas into a chat turn", () => {
		let state = emptyLiveTranscript();
		state = appendLiveTranscript(state, "user", "explain ", false);
		state = appendLiveTranscript(state, "user", "monads", false);
		state = appendLiveTranscript(state, "assistant", "A monad ", false);
		state = appendLiveTranscript(state, "assistant", "sequences effects.", false);
		state = appendLiveTranscript(state, "assistant", "", true);

		expect(state).toEqual({
			turns: [{ user: "explain monads", assistant: "A monad sequences effects." }],
			draft: { user: "", assistant: "" },
		});
	});

	it("uses a provider final transcript without duplicating earlier deltas", () => {
		let state = emptyLiveTranscript();
		state = appendLiveTranscript(state, "user", "What is a closure?", true);
		state = appendLiveTranscript(state, "assistant", "A function ", false);
		state = appendLiveTranscript(state, "assistant", "with captured state.", false);
		state = appendLiveTranscript(state, "assistant", "A function with captured state.", true);

		expect(state.turns).toEqual([{
			user: "What is a closure?",
			assistant: "A function with captured state.",
		}]);
	});

	it("keeps successive live turns separate", () => {
		let state = emptyLiveTranscript();
		state = appendLiveTranscript(state, "user", "first", false);
		state = appendLiveTranscript(state, "assistant", "one", true);
		state = appendLiveTranscript(state, "user", "second", false);
		state = appendLiveTranscript(state, "assistant", "two", true);

		expect(state.turns).toEqual([
			{ user: "first", assistant: "one" },
			{ user: "second", assistant: "two" },
		]);
	});

	it("flushes a partial turn when a session ends", () => {
		let state = emptyLiveTranscript();
		state = appendLiveTranscript(state, "user", "unfinished question", false);

		expect(flushLiveTranscript(state).turns).toEqual([
			{ user: "unfinished question", assistant: "" },
		]);
	});

	it("does not create blank turns", () => {
		const state = appendLiveTranscript(emptyLiveTranscript(), "assistant", "", true);
		expect(flushLiveTranscript(state)).toEqual(emptyLiveTranscript());
	});
});

import type { Api, Model } from "@earendil-works/pi-ai/compat";

export const LONG_CONTEXT_THRESHOLD = 256_000;

export const CHAT_CAPABILITY_FILTERS = [
	{ value: "thinking", label: "Thinking" },
	{ value: "vision", label: "Vision" },
	{ value: "long-context", label: "Long context" },
] as const;

export type ChatCapabilityFilter = (typeof CHAT_CAPABILITY_FILTERS)[number]["value"];

export function modelHasCapability(model: Model<Api>, capability: ChatCapabilityFilter): boolean {
	switch (capability) {
		case "thinking":
			return model.reasoning === true;
		case "vision":
			return model.input.includes("image");
		case "long-context":
			return model.contextWindow >= LONG_CONTEXT_THRESHOLD;
		default:
			return true;
	}
}

export function modelHasCapabilities(model: Model<Api>, capabilities: readonly ChatCapabilityFilter[]): boolean {
	return capabilities.every((capability) => modelHasCapability(model, capability));
}

export function modelCapabilityBadges(model: Model<Api>): string[] {
	return [
		model.input.includes("image") ? "Vision" : "",
		model.reasoning ? "Thinking" : "",
		model.contextWindow >= LONG_CONTEXT_THRESHOLD ? "Long context" : "",
	].filter(Boolean);
}
import { describe, expect, test } from "bun:test";
import type { Api, Model } from "@earendil-works/pi-ai/compat";
import {
	modelCapabilityBadges,
